import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import type { Database } from '@/lib/supabase/types'

export type Project = Database['public']['Tables']['projects']['Row']
export type ProjectReference = Database['public']['Tables']['project_references']['Row']
export type ProjectProgressPhoto = Database['public']['Tables']['project_progress_photos']['Row']

export type ProjectStatus = Project['status']
export type ProjectPhotoKind = ProjectProgressPhoto['kind']

/** Project list item — includes joined data for list cards */
export interface ProjectListItem extends Project {
  client: {
    id: string
    first_name: string
    last_name: string | null
    avatar_url: string | null
  } | null
  primary_artist: {
    id: string
    display_name: string
    avatar_url: string | null
    sort_order: number
  } | null
  sessions_completed: number
  deposit_balance: number
}

/** Full project + related data for detail page */
export interface ProjectWithSessions extends Project {
  client: {
    id: string
    first_name: string
    last_name: string | null
    avatar_url: string | null
    email: string | null
  } | null
  primary_artist: {
    id: string
    display_name: string
    avatar_url: string | null
    sort_order: number
  } | null
  sessions: ProjectSession[]
}

export interface ProjectSession {
  id: string
  scheduled_at: string
  session_number: number | null
  status: Database['public']['Tables']['bookings']['Row']['status']
  price_cents: number
  deposit_paid: boolean
  deposit_cents: number
  service: { id: string; name: string; color: string | null } | null
  artist: { id: string; display_name: string; avatar_url: string | null } | null
}

export interface ProjectDepositLedger {
  total_pool_cents: number
  applied_cents: number
  balance_cents: number
  allocations: {
    booking_id: string
    session_number: number | null
    scheduled_at: string
    amount_cents: number
  }[]
}

export interface ListProjectsFilters {
  status?: ProjectStatus
  artistId?: string
  clientId?: string
  search?: string
}

/**
 * List all projects for a studio with joined client + artist + deposit balance.
 */
export async function listProjects(
  studioId: string,
  filters: ListProjectsFilters = {}
): Promise<ProjectListItem[]> {
  const supabase = await createClient()

  let query = supabase
    .from('projects')
    .select(`
      id, studio_id, client_id, primary_artist_id, name, description,
      placement, style, status, total_sessions_planned, total_price_cents,
      deposit_pool_cents, deposit_applied_cents, moodboard_url, cover_photo_url,
      started_at, completed_at, created_at, updated_at,
      client:clients!projects_client_id_fkey(id, first_name, last_name),
      primary_artist:artists!projects_primary_artist_id_fkey(id, display_name, avatar_url, sort_order)
    `)
    .eq('studio_id', studioId)
    .order('updated_at', { ascending: false })

  if (filters.status) {
    query = query.eq('status', filters.status)
  }
  if (filters.artistId) {
    query = query.eq('primary_artist_id', filters.artistId)
  }
  if (filters.clientId) {
    query = query.eq('client_id', filters.clientId)
  }
  if (filters.search) {
    query = query.ilike('name', `%${filters.search}%`)
  }

  const { data, error } = await query.limit(100)

  if (error) {
    logger.error({ error, studioId }, 'listProjects query failed')
    throw new Error('Failed to load projects')
  }

  // Count completed sessions per project via separate query for each project
  const projectIds = (data ?? []).map((p) => p.id)
  let sessionCounts: Record<string, number> = {}

  if (projectIds.length > 0) {
    const { data: sessionsData } = await supabase
      .from('bookings')
      .select('project_id, status')
      .in('project_id', projectIds)
      .eq('status', 'completed')
      .eq('studio_id', studioId)

    for (const s of sessionsData ?? []) {
      if (!s.project_id) continue
      sessionCounts[s.project_id] = (sessionCounts[s.project_id] ?? 0) + 1
    }
  }

  return (data ?? []).map((p) => ({
    ...p,
    client: Array.isArray(p.client) ? (p.client[0] ?? null) : (p.client ?? null),
    primary_artist: Array.isArray(p.primary_artist) ? (p.primary_artist[0] ?? null) : (p.primary_artist ?? null),
    sessions_completed: sessionCounts[p.id] ?? 0,
    deposit_balance: Math.max(0, p.deposit_pool_cents - p.deposit_applied_cents),
  }))
}

/**
 * Get a single project by ID.
 */
export async function getProject(studioId: string, id: string): Promise<Project | null> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('projects')
    .select('*')
    .eq('id', id)
    .eq('studio_id', studioId)
    .single()

  if (error) {
    if (error.code === 'PGRST116') return null
    logger.error({ error, studioId, id }, 'getProject query failed')
    throw new Error('Failed to load project')
  }

  return data
}

/**
 * Get project + client + artist + sessions for detail page.
 */
export async function getProjectWithSessions(
  studioId: string,
  id: string
): Promise<ProjectWithSessions | null> {
  const supabase = await createClient()

  const [projectResult, sessionsResult] = await Promise.all([
    supabase
      .from('projects')
      .select(`
        id, studio_id, client_id, primary_artist_id, name, description,
        placement, style, status, total_sessions_planned, total_price_cents,
        deposit_pool_cents, deposit_applied_cents, moodboard_url, cover_photo_url,
        started_at, completed_at, created_at, updated_at,
        client:clients!projects_client_id_fkey(id, first_name, last_name, email),
        primary_artist:artists!projects_primary_artist_id_fkey(id, display_name, avatar_url, sort_order)
      `)
      .eq('id', id)
      .eq('studio_id', studioId)
      .single(),
    supabase
      .from('bookings')
      .select(`
        id, scheduled_at, session_number, status, price_cents,
        deposit_paid, deposit_cents,
        service:services!bookings_service_id_fkey(id, name, color),
        artist:artists!bookings_artist_id_fkey(id, display_name, avatar_url)
      `)
      .eq('project_id', id)
      .eq('studio_id', studioId)
      .order('session_number', { ascending: true, nullsFirst: false })
  ])

  if (projectResult.error) {
    if (projectResult.error.code === 'PGRST116') return null
    logger.error({ error: projectResult.error, id }, 'getProjectWithSessions failed')
    throw new Error('Failed to load project')
  }

  const p = projectResult.data

  const sessions: ProjectSession[] = (sessionsResult.data ?? []).map((b) => ({
    id: b.id,
    scheduled_at: b.scheduled_at,
    session_number: b.session_number,
    status: b.status,
    price_cents: b.price_cents,
    deposit_paid: b.deposit_paid,
    deposit_cents: b.deposit_cents,
    service: Array.isArray(b.service) ? (b.service[0] ?? null) : (b.service ?? null),
    artist: Array.isArray(b.artist) ? (b.artist[0] ?? null) : (b.artist ?? null),
  }))

  return {
    ...p,
    client: Array.isArray(p.client) ? (p.client[0] ?? null) : (p.client ?? null),
    primary_artist: Array.isArray(p.primary_artist) ? (p.primary_artist[0] ?? null) : (p.primary_artist ?? null),
    sessions,
  }
}

/**
 * Get reference images for a project (ordered for moodboard).
 */
export async function getProjectReferences(
  studioId: string,
  projectId: string
): Promise<ProjectReference[]> {
  const supabase = await createClient()

  // Verify studio ownership via join before returning
  const { data, error } = await supabase
    .from('project_references')
    .select('*')
    .eq('project_id', projectId)
    .order('display_order', { ascending: true })

  if (error) {
    logger.error({ error, projectId }, 'getProjectReferences failed')
    throw new Error('Failed to load references')
  }

  return data ?? []
}

/**
 * Get progress photos for a project, optionally filtered by kind.
 */
export async function getProjectProgressPhotos(
  studioId: string,
  projectId: string,
  kind?: ProjectPhotoKind
): Promise<ProjectProgressPhoto[]> {
  const supabase = await createClient()

  let query = supabase
    .from('project_progress_photos')
    .select('*')
    .eq('project_id', projectId)
    .order('display_order', { ascending: true })

  if (kind) {
    query = query.eq('kind', kind)
  }

  const { data, error } = await query

  if (error) {
    logger.error({ error, projectId }, 'getProjectProgressPhotos failed')
    throw new Error('Failed to load progress photos')
  }

  return data ?? []
}

/**
 * Get deposit ledger for a project — pool, applied, balance, per-session allocations.
 */
export async function getProjectDepositLedger(
  studioId: string,
  projectId: string
): Promise<ProjectDepositLedger> {
  const supabase = await createClient()

  const [projectResult, sessionsResult] = await Promise.all([
    supabase
      .from('projects')
      .select('deposit_pool_cents, deposit_applied_cents')
      .eq('id', projectId)
      .eq('studio_id', studioId)
      .single(),
    supabase
      .from('bookings')
      .select('id, session_number, scheduled_at, deposit_cents, deposit_paid')
      .eq('project_id', projectId)
      .eq('studio_id', studioId)
      .eq('deposit_paid', true)
      .order('session_number', { ascending: true, nullsFirst: false }),
  ])

  if (projectResult.error || !projectResult.data) {
    logger.error({ error: projectResult.error, projectId }, 'getProjectDepositLedger failed')
    throw new Error('Failed to load deposit ledger')
  }

  const { deposit_pool_cents, deposit_applied_cents } = projectResult.data

  const allocations = (sessionsResult.data ?? []).map((b) => ({
    booking_id: b.id,
    session_number: b.session_number,
    scheduled_at: b.scheduled_at,
    amount_cents: b.deposit_cents,
  }))

  return {
    total_pool_cents: deposit_pool_cents,
    applied_cents: deposit_applied_cents,
    balance_cents: Math.max(0, deposit_pool_cents - deposit_applied_cents),
    allocations,
  }
}

/**
 * Count active projects — used for sidebar badge.
 */
export async function getActiveProjectsCount(studioId: string): Promise<number> {
  const supabase = await createClient()

  const { count, error } = await supabase
    .from('projects')
    .select('id', { count: 'exact', head: true })
    .eq('studio_id', studioId)
    .eq('status', 'active')

  if (error) {
    logger.error({ error, studioId }, 'getActiveProjectsCount failed')
    return 0
  }

  return count ?? 0
}

/**
 * Get projects for a specific client — used on client detail page.
 */
export async function getProjectsByClient(
  studioId: string,
  clientId: string
): Promise<ProjectListItem[]> {
  return listProjects(studioId, { clientId })
}

import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import type { Database } from '@/lib/supabase/types'
import type {
  ProjectCreateInput,
  ProjectUpdateInput,
  AddReferenceInput,
  AddProgressPhotoInput,
} from './schemas'

type Project = Database['public']['Tables']['projects']['Row']
type ProjectReference = Database['public']['Tables']['project_references']['Row']
type ProjectProgressPhoto = Database['public']['Tables']['project_progress_photos']['Row']

/**
 * Create a new project. Returns the newly created project row.
 */
export async function createProject(
  studioId: string,
  input: ProjectCreateInput
): Promise<Project> {
  const supabase = await createClient()

  const { data: { user } } = await supabase.auth.getUser()

  const insertData: Database['public']['Tables']['projects']['Insert'] = {
    studio_id: studioId,
    client_id: input.clientId,
    name: input.name,
    description: input.description ?? null,
    placement: input.placement ?? null,
    style: input.style ?? null,
    primary_artist_id: input.primaryArtistId ?? null,
    total_sessions_planned: input.totalSessionsPlanned ?? null,
    total_price_cents: input.totalPriceCents,
    deposit_pool_cents: input.initialDepositCents ?? 0,
    deposit_applied_cents: 0,
    moodboard_url: input.moodboardUrl || null,
    status: 'active',
    started_at: new Date().toISOString(),
  }

  const { data, error } = await supabase
    .from('projects')
    .insert(insertData)
    .select()
    .single()

  if (error) {
    logger.error({ error, studioId, userId: user?.id }, 'createProject failed')
    throw new Error('Failed to create project')
  }

  return data
}

/**
 * Update an existing project's fields.
 */
export async function updateProject(
  studioId: string,
  id: string,
  input: ProjectUpdateInput
): Promise<Project> {
  const supabase = await createClient()

  const updateData: Database['public']['Tables']['projects']['Update'] = {}
  if (input.name !== undefined) updateData.name = input.name
  if (input.description !== undefined) updateData.description = input.description
  if (input.placement !== undefined) updateData.placement = input.placement
  if (input.style !== undefined) updateData.style = input.style
  if (input.primaryArtistId !== undefined) updateData.primary_artist_id = input.primaryArtistId
  if (input.totalSessionsPlanned !== undefined) updateData.total_sessions_planned = input.totalSessionsPlanned
  if (input.totalPriceCents !== undefined) updateData.total_price_cents = input.totalPriceCents
  if (input.moodboardUrl !== undefined) updateData.moodboard_url = input.moodboardUrl || null
  if (input.coverPhotoUrl !== undefined) updateData.cover_photo_url = input.coverPhotoUrl
  if (input.status !== undefined) updateData.status = input.status
  if (input.startedAt !== undefined) updateData.started_at = input.startedAt
  if (input.completedAt !== undefined) updateData.completed_at = input.completedAt

  const { data, error } = await supabase
    .from('projects')
    .update(updateData)
    .eq('id', id)
    .eq('studio_id', studioId)
    .select()
    .single()

  if (error) {
    logger.error({ error, id, studioId }, 'updateProject failed')
    throw new Error('Failed to update project')
  }

  return data
}

/**
 * Mark a project as completed.
 */
export async function completeProject(studioId: string, id: string): Promise<Project> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('projects')
    .update({ status: 'completed', completed_at: new Date().toISOString() })
    .eq('id', id)
    .eq('studio_id', studioId)
    .select()
    .single()

  if (error) {
    logger.error({ error, id, studioId }, 'completeProject failed')
    throw new Error('Failed to complete project')
  }

  return data
}

/**
 * Archive (soft-cancel) a project.
 */
export async function archiveProject(studioId: string, id: string): Promise<Project> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('projects')
    .update({ status: 'cancelled' })
    .eq('id', id)
    .eq('studio_id', studioId)
    .select()
    .single()

  if (error) {
    logger.error({ error, id, studioId }, 'archiveProject failed')
    throw new Error('Failed to archive project')
  }

  return data
}

/**
 * Link a booking to a project. The DB trigger auto-sets session_number.
 */
export async function linkBookingToProject(
  studioId: string,
  bookingId: string,
  projectId: string
): Promise<void> {
  const supabase = await createClient()

  const { error } = await supabase
    .from('bookings')
    .update({ project_id: projectId })
    .eq('id', bookingId)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ error, bookingId, projectId }, 'linkBookingToProject failed')
    throw new Error('Failed to link booking to project')
  }
}

/**
 * Unlink a booking from its project.
 */
export async function unlinkBookingFromProject(
  studioId: string,
  bookingId: string
): Promise<void> {
  const supabase = await createClient()

  const { error } = await supabase
    .from('bookings')
    .update({ project_id: null, session_number: null })
    .eq('id', bookingId)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ error, bookingId }, 'unlinkBookingFromProject failed')
    throw new Error('Failed to unlink booking from project')
  }
}

/**
 * Add a reference image to a project's moodboard.
 */
export async function addProjectReference(
  studioId: string,
  projectId: string,
  input: AddReferenceInput
): Promise<ProjectReference> {
  const supabase = await createClient()

  const { data: { user } } = await supabase.auth.getUser()

  // Verify project belongs to studio
  const { data: project, error: projectError } = await supabase
    .from('projects')
    .select('id')
    .eq('id', projectId)
    .eq('studio_id', studioId)
    .single()

  if (projectError || !project) {
