/**
 * Batch reorder reference images by updating display_order.
 */
export async function reorderProjectReferences(
  studioId: string,
  projectId: string,
  orderedIds: string[]
): Promise<void> {
  const supabase = await createClient()

  const updates = orderedIds.map((id, index) =>
    supabase
      .from('project_references')
      .update({ display_order: index })
      .eq('id', id)
      .eq('project_id', projectId)
