/**
 * Add funds to the project deposit pool (records a manual ledger entry).
 * Actual payment capture is handled by the Dodo Payments flow.
 */
export async function recordDepositToProject(
  studioId: string,
  projectId: string,
  amountCents: number
): Promise<void> {
  const supabase = await createClient()

  // Verify project belongs to studio + RLS
  const { data: project, error: fetchError } = await supabase
    .from('projects')
    .select('deposit_pool_cents')
    .eq('id', projectId)
    .eq('studio_id', studioId)
    .single()

  if (fetchError || !project) {
    throw new Error('Project not found')
  }

  const { error } = await supabase
    .from('projects')
    .update({
      deposit_pool_cents: project.deposit_pool_cents + amountCents,
    })
    .eq('id', projectId)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ error, projectId, amountCents }, 'recordDepositToProject failed')
    throw new Error('Failed to record deposit')
  }
}

/**
 * Allocate a portion of the deposit pool to a specific session.
 * Guards against over-allocation: applied <= pool.
 */
export async function allocateDepositToSession(
  studioId: string,
  projectId: string,
  bookingId: string,
  amountCents: number
): Promise<void> {
  const supabase = await createClient()

  const { data: project, error: fetchError } = await supabase
    .from('projects')
    .select('deposit_pool_cents, deposit_applied_cents')
    .eq('id', projectId)
    .eq('studio_id', studioId)
    .single()

  if (fetchError || !project) {
    throw new Error('Project not found')
  }

  const newApplied = project.deposit_applied_cents + amountCents
  if (newApplied > project.deposit_pool_cents) {
    throw new Error('Allocation would exceed deposit pool balance')
  }

  // Update the project's applied total and mark the booking deposit as paid
  const [projectUpdate, bookingUpdate] = await Promise.all([
    supabase
      .from('projects')
      .update({ deposit_applied_cents: newApplied })
      .eq('id', projectId)
      .eq('studio_id', studioId),
    supabase
      .from('bookings')
      .update({
        deposit_paid: true,
        deposit_paid_at: new Date().toISOString(),
        deposit_cents: amountCents,
      })
      .eq('id', bookingId)
      .eq('studio_id', studioId),
  ])

  if (projectUpdate.error || bookingUpdate.error) {
    logger.error(
      { projectError: projectUpdate.error, bookingError: bookingUpdate.error, projectId, bookingId },
      'allocateDepositToSession failed'
    )
    throw new Error('Failed to allocate deposit')
  }
}

