type ActionResult<T = void> =
  | { ok: true; data: T }
  | { ok: false; error: string }

type MutationRole = 'owner' | 'admin' | 'artist'
type ReadRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'

function canWrite(role: ReadRole): role is MutationRole {
  return role === 'owner' || role === 'admin' || role === 'artist'
}

function canAdmin(role: ReadRole): boolean {
  return role === 'owner' || role === 'admin'
}

// ─── Create ────────────────────────────────────────────────────────────────────

export async function createProjectAction(
  formData: FormData
): Promise<ActionResult<{ id: string }>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }

  const role = auth.role as ReadRole
  // Receptionist can create projects per RLS
  if (role === 'guest_artist') return { ok: false, error: 'Insufficient permissions' }

  const raw = {
    clientId: formData.get('clientId'),
    name: formData.get('name'),
    description: formData.get('description') || undefined,
    placement: formData.get('placement') || undefined,
    style: formData.get('style') || undefined,
    primaryArtistId: formData.get('primaryArtistId') || undefined,
    totalSessionsPlanned: formData.get('totalSessionsPlanned')
      ? Number(formData.get('totalSessionsPlanned'))
      : undefined,
    totalPriceCents: formData.get('totalPriceCents')
      ? Number(formData.get('totalPriceCents'))
      : 0,
    moodboardUrl: formData.get('moodboardUrl') || undefined,
    initialDepositCents: formData.get('initialDepositCents')
      ? Number(formData.get('initialDepositCents'))
      : undefined,
  }

  const parsed = projectCreateSchema.safeParse(raw)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
  }

  try {
    const project = await createProject(auth.studioId, parsed.data)
    revalidatePath('/projects')
    return { ok: true, data: { id: project.id } }
  } catch (err) {
    logger.error({ err }, 'createProjectAction failed')
    return { ok: false, error: 'Failed to create project' }
  }
}

