import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { listProjects } from '@/lib/projects/queries'
import { ProjectsListClient } from '@/components/projects/ProjectsListClient'
import { Skeleton } from '@/components/ui/skeleton'
import type { ListProjectsFilters } from '@/lib/projects/queries'
import type { ProjectStatus } from '@/lib/projects/queries'

export const metadata: Metadata = {
  title: 'Projects — InkOS',
}

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function ProjectsPage({ searchParams }: Props) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const params = await searchParams

  const getParam = (key: string) =>
    typeof params[key] === 'string' ? (params[key] as string) : undefined

  const filters: ListProjectsFilters = {}
  const statusParam = getParam('status')
  if (statusParam && ['active', 'completed', 'on_hold', 'cancelled'].includes(statusParam)) {
    filters.status = statusParam as ProjectStatus
  }
  const artistIdParam = getParam('artistId')
  if (artistIdParam) filters.artistId = artistIdParam
  const clientIdParam = getParam('clientId')
  if (clientIdParam) filters.clientId = clientIdParam
  const searchParam = getParam('search')
  if (searchParam) filters.search = searchParam

  const supabase = await createClient()

  const [projects, artistsResult] = await Promise.all([
    listProjects(auth.studioId, filters),
    supabase
      .from('artists')
      .select('id, display_name, avatar_url, sort_order')
      .eq('studio_id', auth.studioId)
      .eq('status', 'active')
      .order('sort_order'),
  ])

  const artists = artistsResult.data ?? []

  return (
    <div className="flex flex-col flex-1 min-h-0">
      <Suspense
        fallback={
          <div className="p-6 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {Array.from({ length: 8 }).map((_, i) => (
              <Skeleton key={i} className="h-64 rounded-xl" />
            ))}
          </div>
        }
      >
        <ProjectsListClient
          initialProjects={projects}
          artists={artists}
          role={auth.role}
          initialFilters={filters}
        />
      </Suspense>
    </div>
  )
}

