    project.total_sessions_planned
      ? `Session ${project.sessions_completed} of ${project.total_sessions_planned}`
      : `${project.sessions_completed} session${project.sessions_completed !== 1 ? 's' : ''} · open-ended`

  const depositLabel =
    project.deposit_pool_cents > 0
      ? project.deposit_balance === 0
        ? `Deposit paid · ${formatCurrency(project.deposit_pool_cents)}`
        : `Balance due · ${formatCurrency(project.deposit_balance)}`
