'use client'

import { useState, useCallback, useTransition, useRef, useEffect } from 'react'
import { useRouter, useSearchParams, usePathname } from 'next/navigation'
import Link from 'next/link'
import {
  FolderKanban,
  LayoutGrid,
  List,
  Plus,
  Search,
  X,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Skeleton } from '@/components/ui/skeleton'
import { Badge } from '@/components/ui/badge'
import { cn, formatCurrency, formatDate } from '@/lib/utils'
import { ProjectCard } from './ProjectCard'
import type { ProjectListItem } from '@/lib/projects/queries'
import type { ListProjectsFilters, ProjectStatus } from '@/lib/projects/queries'

interface Artist {
  id: string
  display_name: string
  avatar_url: string | null
  sort_order: number
}

interface ProjectsListClientProps {
  initialProjects: ProjectListItem[]
  artists: Artist[]
  role: string
  initialFilters: ListProjectsFilters
}

const STATUS_LABELS: Record<string, string> = {
  active: 'Active',
  completed: 'Completed',
  on_hold: 'On Hold',
  cancelled: 'Archived',
}

const TABLE_STATUS_CONFIG: Record<string, string> = {
  active: 'bg-success-bg text-success-foreground',
  completed: 'bg-secondary text-secondary-foreground',
  on_hold: 'bg-warning-bg text-warning-foreground',
  cancelled: 'bg-muted text-muted-foreground',
}

export function ProjectsListClient({
  initialProjects,
  artists,
  role,
  initialFilters,
}: ProjectsListClientProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const [isPending, startTransition] = useTransition()
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid')

  // Local search state (debounced → URL)
  const [searchValue, setSearchValue] = useState(initialFilters.search ?? '')
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const updateParam = useCallback(
    (key: string, value: string | null) => {
      const current = new URLSearchParams(Array.from(searchParams.entries()))
      if (value && value !== 'all') {
        current.set(key, value)
      } else {
        current.delete(key)
      }
      const qs = current.toString()
      startTransition(() => {
        router.push(`${pathname}${qs ? `?${qs}` : ''}`)
      })
    },
    [router, pathname, searchParams]
  )

  const handleSearchChange = useCallback(
    (value: string) => {
      setSearchValue(value)
      if (debounceRef.current) clearTimeout(debounceRef.current)
      debounceRef.current = setTimeout(() => {
        updateParam('search', value || null)
      }, 300)
    },
    [updateParam]
  )

  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current)
    }
  }, [])

  const activeStatus = searchParams.get('status') ?? 'all'
  const activeArtist = searchParams.get('artistId') ?? 'all'

  const canCreate = role !== 'guest_artist'

  return (
    <div className="flex flex-col flex-1 min-h-0">
      {/* Page header */}
      <div className="px-4 sm:px-6 pt-6 pb-0 flex items-start justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-foreground">Projects</h1>
          <p className="mt-0.5 text-sm text-muted-foreground">
            Multi-session tattoo projects — sleeves, back pieces, bodysuits
          </p>
        </div>
        {canCreate && (
          <Button asChild size="sm">
            <Link href="/projects/new">
              <Plus className="h-4 w-4" />
              New Project
            </Link>
          </Button>
        )}
      </div>

      {/* Filter bar */}
      <div className="px-4 sm:px-6 mt-4 flex flex-wrap items-center gap-2">
        {/* Search */}
        <div className="relative flex-1 min-w-[200px] max-w-xs">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
          <Input
            placeholder="Search projects…"
            value={searchValue}
            onChange={(e) => handleSearchChange(e.target.value)}
            className="pl-8 h-8 text-sm"
          />
          {searchValue && (
            <button
              onClick={() => handleSearchChange('')}
              className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              aria-label="Clear search"
            >
              <X className="h-3 w-3" />
            </button>
          )}
        </div>

        {/* Status filter */}
        <Select value={activeStatus} onValueChange={(v) => updateParam('status', v)}>
          <SelectTrigger className="h-8 w-36 text-sm">
            <SelectValue placeholder="Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All statuses</SelectItem>
            <SelectItem value="active">Active</SelectItem>
            <SelectItem value="completed">Completed</SelectItem>
            <SelectItem value="on_hold">On Hold</SelectItem>
            <SelectItem value="cancelled">Archived</SelectItem>
          </SelectContent>
        </Select>

        {/* Artist filter */}
        {artists.length > 0 && (
          <Select value={activeArtist} onValueChange={(v) => updateParam('artistId', v)}>
            <SelectTrigger className="h-8 w-40 text-sm">
              <SelectValue placeholder="Artist" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All artists</SelectItem>
              {artists.map((a) => (
                <SelectItem key={a.id} value={a.id}>
                  {a.display_name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* View toggle */}
        <div className="ml-auto flex items-center gap-1 rounded-md border border-border p-0.5">
          <button
            onClick={() => setViewMode('grid')}
            className={cn(
              'p-1.5 rounded text-muted-foreground transition-colors',
              viewMode === 'grid' && 'bg-accent text-accent-foreground'
            )}
            aria-label="Grid view"
          >
            <LayoutGrid className="h-3.5 w-3.5" />
          </button>
          <button
            onClick={() => setViewMode('table')}
            className={cn(
              'p-1.5 rounded text-muted-foreground transition-colors',
              viewMode === 'table' && 'bg-accent text-accent-foreground'
            )}
            aria-label="Table view"
          >
            <List className="h-3.5 w-3.5" />
          </button>
        </div>
      </div>

      {/* Content area */}
      <div className="flex-1 px-4 sm:px-6 py-4">
        {isPending ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {Array.from({ length: 6 }).map((_, i) => (
              <Skeleton key={i} className="h-64 rounded-xl" />
            ))}
          </div>
        ) : initialProjects.length === 0 ? (
          <EmptyProjects canCreate={canCreate} />
        ) : viewMode === 'grid' ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {initialProjects.map((project) => (
              <ProjectCard key={project.id} project={project} />
            ))}
          </div>
        ) : (
          <ProjectsTable projects={initialProjects} />
        )}
      </div>
    </div>
  )
}

// ── Empty state ────────────────────────────────────────────────────────────────

function EmptyProjects({ canCreate }: { canCreate: boolean }) {
  return (
    <div className="flex flex-col items-center justify-center py-20 text-center">
      <div className="h-14 w-14 rounded-full bg-muted flex items-center justify-center mb-4">
        <FolderKanban className="h-7 w-7 text-muted-foreground" />
      </div>
      <h3 className="text-base font-semibold text-foreground mb-1">No projects yet</h3>
      <p className="text-sm text-muted-foreground max-w-xs mb-4">
        Projects group multi-session tattoos — sleeves, back pieces, bodysuits — into a single
        workflow with shared deposits and photo progression.
      </p>
      {canCreate && (
        <Button asChild size="sm">
          <Link href="/projects/new">
            <Plus className="h-4 w-4" />
            Start your first project
          </Link>
        </Button>
      )}
    </div>
  )
}

// ── Table view ─────────────────────────────────────────────────────────────────

function ProjectsTable({ projects }: { projects: ProjectListItem[] }) {
  return (
    <div className="rounded-lg border border-border overflow-hidden">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Project</TableHead>
            <TableHead>Client</TableHead>
            <TableHead className="hidden sm:table-cell">Artist</TableHead>
            <TableHead className="hidden md:table-cell">Sessions</TableHead>
            <TableHead className="hidden lg:table-cell">Deposit</TableHead>
            <TableHead>Status</TableHead>
            <TableHead className="hidden xl:table-cell text-right">Updated</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {projects.map((project) => {
            const clientName = project.client
              ? `${project.client.first_name}${project.client.last_name ? ` ${project.client.last_name}` : ''}`
              : '—'

            const sessionLabel = project.total_sessions_planned
              ? `${project.sessions_completed} / ${project.total_sessions_planned}`
              : `${project.sessions_completed}`

            const statusClass = TABLE_STATUS_CONFIG[project.status] ?? TABLE_STATUS_CONFIG.active
            const statusLabel = STATUS_LABELS[project.status] ?? project.status

            return (
              <TableRow
                key={project.id}
                className="cursor-pointer hover:bg-muted/50 transition-colors"
                onClick={() => {
                  window.location.href = `/projects/${project.id}`
                }}
              >
                <TableCell>
                  <div className="font-medium text-sm text-foreground line-clamp-1">
                    {project.name}
                  </div>
                  {project.placement && (
                    <div className="text-xs text-muted-foreground line-clamp-1">
                      {project.placement}
                    </div>
                  )}
                </TableCell>
                <TableCell className="text-sm text-muted-foreground">{clientName}</TableCell>
                <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                  {project.primary_artist?.display_name ?? '—'}
                </TableCell>
                <TableCell className="hidden md:table-cell text-sm">{sessionLabel}</TableCell>
                <TableCell className="hidden lg:table-cell text-sm">
                  {project.deposit_pool_cents > 0
                    ? formatCurrency(project.deposit_pool_cents)
                    : '—'}
                </TableCell>
                <TableCell>
                  <span
                    className={cn(
                      'px-2 py-0.5 rounded-full text-[11px] font-medium',
                      statusClass
                    )}
                  >
                    {statusLabel}
                  </span>
                </TableCell>
                <TableCell className="hidden xl:table-cell text-xs text-muted-foreground text-right">
                  {formatDate(project.updated_at)}
                </TableCell>
              </TableRow>
            )
          })}
        </TableBody>
      </Table>
    </div>
  )
}

'use client'

import { useState, useTransition, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { MoneyInput } from '@/components/ui/money-input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from '@/components/ui/card'
import { ComboBox } from '@/components/ui/combobox'
import { Loader2 } from 'lucide-react'
import { createProjectAction } from '@/app/(app)/projects/actions'
import { PROJECT_STYLES } from '@/lib/projects/schemas'
import type { ComboBoxOption } from '@/components/ui/combobox'

const STYLE_LABELS: Record<string, string> = {
  traditional: 'Traditional',
  realism: 'Realism',
  neo_trad: 'Neo Traditional',
  blackwork: 'Blackwork',
  japanese: 'Japanese',
  tribal: 'Tribal',
  watercolor: 'Watercolor',
  fine_line: 'Fine Line',
  custom: 'Custom / Other',
}

interface Artist {
  id: string
  display_name: string
  avatar_url: string | null
  sort_order: number
}

interface Client {
  id: string
  first_name: string
  last_name: string | null
  email: string | null
}

interface NewProjectFormProps {
  artists: Artist[]
  clients: Client[]
}

export function NewProjectForm({ artists, clients }: NewProjectFormProps) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [errors, setErrors] = useState<Record<string, string>>({})

  const [clientId, setClientId] = useState<string | null>(null)
  const [primaryArtistId, setPrimaryArtistId] = useState<string | null>(null)
  const [name, setName] = useState('')
  const [description, setDescription] = useState('')
  const [placement, setPlacement] = useState('')
  const [style, setStyle] = useState<string>('')
  const [totalSessionsPlanned, setTotalSessionsPlanned] = useState('')
  const [totalPriceCents, setTotalPriceCents] = useState(0)
  const [initialDepositCents, setInitialDepositCents] = useState(0)
  const [moodboardUrl, setMoodboardUrl] = useState('')

  const clientOptions: ComboBoxOption[] = useMemo(
    () =>
      clients.map((c) => ({
        value: c.id,
        label: `${c.first_name}${c.last_name ? ` ${c.last_name}` : ''}`,
        description: c.email ?? undefined,
      })),
    [clients]
  )

  const artistOptions: ComboBoxOption[] = useMemo(
    () =>
      artists.map((a) => ({
        value: a.id,
        label: a.display_name,
      })),
    [artists]
  )

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    setErrors({})

    if (!clientId) {
      setErrors({ clientId: 'Please select a client' })
      return
    }
    if (!name.trim()) {
      setErrors({ name: 'Project name is required' })
      return
    }

    const fd = new FormData()
    fd.set('clientId', clientId)
    fd.set('name', name.trim())
    if (description) fd.set('description', description)
    if (placement) fd.set('placement', placement)
    if (style) fd.set('style', style)
    if (primaryArtistId) fd.set('primaryArtistId', primaryArtistId)
    if (totalSessionsPlanned) fd.set('totalSessionsPlanned', totalSessionsPlanned)
    fd.set('totalPriceCents', String(totalPriceCents))
    if (initialDepositCents > 0) fd.set('initialDepositCents', String(initialDepositCents))
    if (moodboardUrl) fd.set('moodboardUrl', moodboardUrl)

    startTransition(async () => {
      const result = await createProjectAction(fd)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success('Project created')
      router.push(`/projects/${result.data.id}`)
    })
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      {/* Card 1: Client + basics */}
      <Card className="shadow-[var(--shadow-card)]">
        <CardHeader className="pb-3">
          <CardTitle className="text-base">Client & Basics</CardTitle>
          <CardDescription className="text-sm">Who is this project for?</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Client */}
          <div className="space-y-1.5">
            <Label htmlFor="client-select">
              Client <span className="text-destructive">*</span>
            </Label>
            <ComboBox
              options={clientOptions}
              value={clientId}
              onValueChange={setClientId}
              placeholder="Search clients…"
              searchPlaceholder="Type to search…"
            />
            {errors.clientId && (
              <p className="text-xs text-destructive">{errors.clientId}</p>
            )}
          </div>

          {/* Project name */}
          <div className="space-y-1.5">
            <Label htmlFor="project-name">
              Project name <span className="text-destructive">*</span>
            </Label>
            <Input
              id="project-name"
              placeholder="e.g. Dragon Sleeve, Back Piece"
              value={name}
              onChange={(e) => setName(e.target.value)}
              maxLength={200}
            />
            {errors.name && <p className="text-xs text-destructive">{errors.name}</p>}
          </div>

          {/* Description */}
          <div className="space-y-1.5">
            <Label htmlFor="project-description">Description</Label>
            <Textarea
              id="project-description"
              placeholder="Brief description of the project…"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
              maxLength={2000}
              className="resize-none"
            />
          </div>

          {/* Placement */}
          <div className="space-y-1.5">
            <Label htmlFor="project-placement">Placement</Label>
            <Input
              id="project-placement"
              placeholder="e.g. Left forearm, Upper back"
              value={placement}
              onChange={(e) => setPlacement(e.target.value)}
              maxLength={100}
            />
          </div>
        </CardContent>
      </Card>

      {/* Card 2: Style + deposit plan */}
      <Card className="shadow-[var(--shadow-card)]">
        <CardHeader className="pb-3">
          <CardTitle className="text-base">Style & Deposit Plan</CardTitle>
          <CardDescription className="text-sm">
            Optional details for planning and deposit tracking.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Style */}
          <div className="space-y-1.5">
            <Label>Style</Label>
            <Select value={style} onValueChange={setStyle}>
              <SelectTrigger>
                <SelectValue placeholder="Select style…" />
              </SelectTrigger>
              <SelectContent>
                {PROJECT_STYLES.map((s) => (
                  <SelectItem key={s} value={s}>
                    {STYLE_LABELS[s] ?? s}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Primary artist */}
          <div className="space-y-1.5">
            <Label>Primary Artist</Label>
            <ComboBox
              options={artistOptions}
              value={primaryArtistId}
              onValueChange={setPrimaryArtistId}
              placeholder="Assign artist…"
              searchPlaceholder="Search artists…"
            />
          </div>

          {/* Sessions planned */}
          <div className="space-y-1.5">
            <Label htmlFor="sessions-planned">Total sessions planned</Label>
            <Input
              id="sessions-planned"
              type="number"
              placeholder="Leave blank for open-ended"
              value={totalSessionsPlanned}
              onChange={(e) => setTotalSessionsPlanned(e.target.value)}
              min={1}
              max={50}
            />
          </div>

          {/* Total price */}
          <div className="space-y-1.5">
            <Label>Total price</Label>
            <MoneyInput
              value={totalPriceCents}
              onChange={setTotalPriceCents}
              placeholder="0.00"
            />
          </div>

          {/* Initial deposit */}
          <div className="space-y-1.5">
            <Label>Initial deposit (optional)</Label>
            <MoneyInput
              value={initialDepositCents}
              onChange={setInitialDepositCents}
              placeholder="0.00"
            />
            <p className="text-xs text-muted-foreground">
              Records a deposit already received into the project pool.
            </p>
          </div>

          {/* Moodboard URL */}
          <div className="space-y-1.5">
            <Label htmlFor="moodboard-url">Moodboard URL</Label>
            <Input
              id="moodboard-url"
              type="url"
              placeholder="https://pinterest.com/…"
              value={moodboardUrl}
              onChange={(e) => setMoodboardUrl(e.target.value)}
            />
          </div>
        </CardContent>
      </Card>

      {/* Submit */}
      <div className="flex items-center justify-end gap-3">
        <Button type="button" variant="outline" onClick={() => router.back()} disabled={isPending}>
          Cancel
        </Button>
        <Button type="submit" disabled={isPending}>
          {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
          Create Project
        </Button>
      </div>
    </form>
  )
}

import type { Metadata } from 'next'
import { redirect, notFound } from 'next/navigation'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import {
  getProjectWithSessions,
  getProjectReferences,
  getProjectProgressPhotos,
  getProjectDepositLedger,
} from '@/lib/projects/queries'
import { ProjectDetailShell } from '@/components/projects/ProjectDetailShell'

interface Props {
  params: Promise<{ id: string }>
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { id } = await params
  return { title: `Project — InkOS` }
}

export default async function ProjectDetailPage({ params, searchParams }: Props) {
  const { id } = await params
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const resolvedParams = await searchParams
  const tab = typeof resolvedParams.tab === 'string' ? resolvedParams.tab : 'sessions'

  // Fetch all data in parallel
  const [project, references, progressPhotos, depositLedger] = await Promise.all([
    getProjectWithSessions(auth.studioId, id),
    getProjectReferences(auth.studioId, id),
    getProjectProgressPhotos(auth.studioId, id),
    getProjectDepositLedger(auth.studioId, id).catch(() => null),
  ])

  if (!project) notFound()

  return (
    <ProjectDetailShell
      project={project}
      references={references}
      progressPhotos={progressPhotos}
      depositLedger={depositLedger ?? {
        total_pool_cents: project.deposit_pool_cents,
        applied_cents: project.deposit_applied_cents,
        balance_cents: Math.max(0, project.deposit_pool_cents - project.deposit_applied_cents),
        allocations: [],
      }}
      role={auth.role}
      initialTab={tab}
    />
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter, usePathname } from 'next/navigation'
import Link from 'next/link'
import {
  FolderKanban,
  MoreHorizontal,
  CheckCircle2,
  Archive,
  Pencil,
} from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { cn } from '@/lib/utils'
import { SessionsTab } from './SessionsTab'
import { DepositTab } from './DepositTab'
import { ReferencesTab } from './ReferencesTab'
import { ProgressTab } from './ProgressTab'
import { DetailsTab } from './DetailsTab'
import { completeProjectAction, archiveProjectAction } from '@/app/(app)/projects/actions'
import type { ProjectWithSessions, ProjectReference, ProjectProgressPhoto, ProjectDepositLedger } from '@/lib/projects/queries'

const TABS = [
  { id: 'sessions', label: 'Sessions' },
  { id: 'deposit', label: 'Deposit' },
  { id: 'references', label: 'References' },
  { id: 'progress', label: 'Progress' },
  { id: 'details', label: 'Details' },
] as const

type TabId = (typeof TABS)[number]['id']

const STATUS_CONFIG: Record<string, { label: string; className: string }> = {
  active: { label: 'Active', className: 'bg-success-bg text-success-foreground' },
  completed: { label: 'Completed', className: 'bg-secondary text-secondary-foreground' },
  on_hold: { label: 'On Hold', className: 'bg-warning-bg text-warning-foreground' },
  cancelled: { label: 'Archived', className: 'bg-muted text-muted-foreground' },
}

interface ProjectDetailShellProps {
  project: ProjectWithSessions
  references: ProjectReference[]
  progressPhotos: ProjectProgressPhoto[]
  depositLedger: ProjectDepositLedger
  role: string
  initialTab: string
}

export function ProjectDetailShell({
  project,
  references,
  progressPhotos,
  depositLedger,
  role,
  initialTab,
}: ProjectDetailShellProps) {
  const router = useRouter()
  const [activeTab, setActiveTab] = useState<TabId>(
    TABS.find((t) => t.id === initialTab)?.id ?? 'sessions'
  )
  const [isPending, startTransition] = useTransition()
  const [showCompleteDialog, setShowCompleteDialog] = useState(false)
  const [showArchiveDialog, setShowArchiveDialog] = useState(false)

  const statusConfig = STATUS_CONFIG[project.status] ?? STATUS_CONFIG.active
  const canWrite = role === 'owner' || role === 'admin' || role === 'artist'
  const canAdmin = role === 'owner' || role === 'admin'

  const handleTabChange = (tabId: TabId) => {
    setActiveTab(tabId)
    // Update URL for deep-linking (non-navigation, just query param)
    const url = new URL(window.location.href)
    url.searchParams.set('tab', tabId)
    router.replace(url.pathname + url.search, { scroll: false })
  }

  const handleComplete = () => {
    startTransition(async () => {
      const result = await completeProjectAction(project.id)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success('Project marked as completed')
      router.refresh()
    })
    setShowCompleteDialog(false)
  }

  const handleArchive = () => {
    startTransition(async () => {
      const result = await archiveProjectAction(project.id)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success('Project archived')
      router.push('/projects')
    })
    setShowArchiveDialog(false)
  }

  const clientName = project.client
    ? `${project.client.first_name}${project.client.last_name ? ` ${project.client.last_name}` : ''}`
    : 'Unknown client'

  return (
    <div className="flex flex-col min-h-0">
      {/* Breadcrumb */}
      <div className="px-4 sm:px-6 pt-4">
        <nav className="flex items-center gap-1.5 text-xs text-muted-foreground">
          <Link href="/projects" className="hover:text-foreground transition-colors">
            Projects
          </Link>
          <span>/</span>
          <span className="text-foreground font-medium truncate max-w-[200px]">
            {project.name}
          </span>
        </nav>
      </div>

      {/* Cover + name header */}
      <div className="relative mt-3 mx-4 sm:mx-6 rounded-xl overflow-hidden bg-gradient-to-br from-primary/10 to-accent/20 aspect-[5/2]">
        {project.cover_photo_url ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={project.cover_photo_url}
            alt={project.name}
            className="h-full w-full object-cover"
          />
        ) : (
          <div className="flex h-full w-full items-center justify-center">
            <FolderKanban className="h-12 w-12 text-primary/20" />
          </div>
        )}

        {/* Gradient overlay */}
        <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent" />

        {/* Bottom-left: name + placement */}
        <div className="absolute bottom-0 left-0 p-4">
          <div className="flex items-center gap-2 mb-1">
            <span
              className={cn(
                'px-2 py-0.5 rounded-full text-[11px] font-medium',
                statusConfig.className
              )}
            >
              {statusConfig.label}
            </span>
            {project.placement && (
              <span className="text-xs text-white/80">{project.placement}</span>
            )}
          </div>
          <h1 className="text-xl font-bold text-white">{project.name}</h1>
          <p className="text-sm text-white/70 mt-0.5">{clientName}</p>
        </div>

        {/* Top-right: kebab menu */}
        {(canWrite || canAdmin) && (
          <div className="absolute top-3 right-3">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  size="icon"
                  variant="secondary"
                  className="h-8 w-8 rounded-lg bg-white/10 hover:bg-white/20 border-white/20 text-white"
                  aria-label="Project options"
                >
                  <MoreHorizontal className="h-4 w-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-44">
                <DropdownMenuItem onClick={() => handleTabChange('details')}>
                  <Pencil className="h-3.5 w-3.5 mr-2" />
                  Edit details
                </DropdownMenuItem>
                {project.status === 'active' && canWrite && (
                  <DropdownMenuItem onClick={() => setShowCompleteDialog(true)}>
                    <CheckCircle2 className="h-3.5 w-3.5 mr-2" />
                    Mark complete
                  </DropdownMenuItem>
                )}
                {canAdmin && project.status !== 'cancelled' && (
                  <>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem
                      className="text-destructive focus:text-destructive"
                      onClick={() => setShowArchiveDialog(true)}
                    >
                      <Archive className="h-3.5 w-3.5 mr-2" />
                      Archive project
                    </DropdownMenuItem>
                  </>
                )}
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        )}
      </div>

      {/* Sticky tab nav */}
      <div className="sticky top-14 z-20 bg-background pt-1 pb-0 -mx-0 border-b border-border/40 mt-0">
        <nav
          className="flex items-center gap-0 px-4 sm:px-6 overflow-x-auto scrollbar-none"
          aria-label="Project tabs"
        >
          {TABS.map((tab) => {
            const isActive = activeTab === tab.id
            return (
              <button
                key={tab.id}
                onClick={() => handleTabChange(tab.id)}
                data-active={isActive}
                className={cn(
                  'relative px-3 py-2.5 text-sm font-medium text-muted-foreground whitespace-nowrap',
                  'hover:text-foreground transition-colors duration-150 ease-out',
                  "after:absolute after:bottom-0 after:left-0 after:right-0 after:h-0.5 after:rounded-full after:transition-opacity after:duration-150",
                  isActive
                    ? 'text-foreground after:bg-primary after:opacity-100'
                    : 'after:opacity-0'
                )}
              >
                {tab.label}
              </button>
            )
          })}
        </nav>
      </div>

      {/* Tab content */}
      <div className="flex-1 px-4 sm:px-6 pt-4 pb-8">
        {activeTab === 'sessions' && (
          <SessionsTab
            project={project}
            role={role}
            onRefresh={() => router.refresh()}
          />
        )}
        {activeTab === 'deposit' && (
          <DepositTab
            project={project}
            ledger={depositLedger}
            role={role}
            onRefresh={() => router.refresh()}
          />
        )}
        {activeTab === 'references' && (
          <ReferencesTab
            project={project}
            references={references}
            role={role}
            onRefresh={() => router.refresh()}
          />
        )}
        {activeTab === 'progress' && (
          <ProgressTab
            project={project}
            photos={progressPhotos}
            role={role}
            onRefresh={() => router.refresh()}
          />
        )}
        {activeTab === 'details' && (
          <DetailsTab
            project={project}
            role={role}
            onRefresh={() => router.refresh()}
            onArchive={canAdmin ? () => setShowArchiveDialog(true) : undefined}
          />
        )}
      </div>

      {/* Confirm complete dialog */}
      <AlertDialog open={showCompleteDialog} onOpenChange={setShowCompleteDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Mark project as completed?</AlertDialogTitle>
            <AlertDialogDescription>
              This will set the project status to completed. You can still view all sessions and
              photos. This action can be undone by editing the Details tab.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleComplete} disabled={isPending}>
              Mark Complete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Confirm archive dialog */}
      <AlertDialog open={showArchiveDialog} onOpenChange={setShowArchiveDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Archive this project?</AlertDialogTitle>
            <AlertDialogDescription>
              Archiving sets the status to cancelled and hides it from the active list.
              All sessions and photos are preserved. You can restore it from the Details tab.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleArchive}
              disabled={isPending}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Archive
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { toast } from 'sonner'
import { CheckCircle2, Circle, CalendarPlus, Unlink, ExternalLink } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { cn, formatCurrency, formatDate } from '@/lib/utils'
import { unlinkBookingAction } from '@/app/(app)/projects/actions'
import type { ProjectWithSessions } from '@/lib/projects/queries'

interface SessionsTabProps {
  project: ProjectWithSessions
  role: string
  onRefresh: () => void
}

const BOOKING_STATUS_CONFIG: Record<string, { label: string; className: string }> = {
  pending: { label: 'Pending', className: 'bg-warning-bg text-warning-foreground' },
  confirmed: { label: 'Confirmed', className: 'bg-secondary text-secondary-foreground' },
  in_progress: { label: 'In Progress', className: 'bg-primary/10 text-primary' },
  completed: { label: 'Completed', className: 'bg-success-bg text-success-foreground' },
  cancelled: { label: 'Cancelled', className: 'bg-muted text-muted-foreground' },
  no_show: { label: 'No Show', className: 'bg-destructive/10 text-destructive' },
}

export function SessionsTab({ project, role, onRefresh }: SessionsTabProps) {
  const [isPending, startTransition] = useTransition()
  const [unlinkingId, setUnlinkingId] = useState<string | null>(null)
  const canAdmin = role === 'owner' || role === 'admin'

  const completedCount = project.sessions.filter((s) => s.status === 'completed').length
  const totalPlanned = project.total_sessions_planned

  const handleUnlink = (bookingId: string) => {
    startTransition(async () => {
      const result = await unlinkBookingAction(project.id, bookingId)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success('Session unlinked from project')
      onRefresh()
    })
    setUnlinkingId(null)
  }

  return (
    <div className="space-y-4 max-w-2xl">
      {/* Header summary */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-base font-semibold text-foreground">
            {totalPlanned
              ? `Session ${completedCount} of ${totalPlanned}`
              : `${project.sessions.length} session${project.sessions.length !== 1 ? 's' : ''}`}
          </h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            {completedCount} completed
            {totalPlanned ? ` · ${totalPlanned - completedCount} remaining` : ''}
          </p>
        </div>
        <Button variant="outline" size="sm" asChild>
          <a href={`/bookings/new?projectId=${project.id}`}>
            <CalendarPlus className="h-3.5 w-3.5" />
            Book next session
          </a>
        </Button>
      </div>

      {/* Timeline */}
      {project.sessions.length === 0 ? (
        <EmptySessions />
      ) : (
        <div className="relative">
          {/* Vertical line */}
          <div className="absolute left-[13px] top-4 bottom-4 w-px bg-border" aria-hidden="true" />

          <ol className="space-y-3">
            {project.sessions.map((session, index) => {
              const isDone = session.status === 'completed'
              const statusConfig = BOOKING_STATUS_CONFIG[session.status] ?? BOOKING_STATUS_CONFIG.pending

              return (
                <li key={session.id} className="relative flex gap-4">
                  {/* Dot */}
                  <div className="relative z-10 mt-1 shrink-0">
                    {isDone ? (
                      <CheckCircle2 className="h-6 w-6 text-success" />
                    ) : (
                      <Circle className="h-6 w-6 text-border" />
                    )}
                  </div>

                  {/* Content */}
                  <div
                    className={cn(
                      'flex-1 rounded-lg border border-border p-3 bg-card',
                      'shadow-[var(--shadow-soft)]'
                    )}
                  >
                    <div className="flex items-start justify-between gap-2">
                      <div className="space-y-1">
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="text-sm font-medium text-foreground">
                            Session {session.session_number ?? index + 1}
                          </span>
                          <span
                            className={cn(
                              'px-2 py-0.5 rounded-full text-[10px] font-medium',
                              statusConfig.className
                            )}
                          >
                            {statusConfig.label}
                          </span>
                          {session.deposit_paid && (
                            <span className="px-2 py-0.5 rounded-full text-[10px] font-medium bg-success-bg text-success-foreground">
                              Deposit paid
                            </span>
                          )}
                        </div>
                        <p className="text-xs text-muted-foreground">
                          {formatDate(session.scheduled_at, {
                            weekday: 'short',
                            month: 'short',
                            day: 'numeric',
                            year: 'numeric',
                          })}
                        </p>
                        {session.service && (
                          <p className="text-xs text-muted-foreground">{session.service.name}</p>
                        )}
                        {session.artist && (
                          <p className="text-xs text-muted-foreground">
                            {session.artist.display_name}
                          </p>
                        )}
                      </div>

                      <div className="flex items-center gap-2 shrink-0">
                        <span className="text-sm font-semibold text-foreground">
                          {formatCurrency(session.price_cents)}
                        </span>

                        <a
                          href={`/bookings/${session.id}`}
                          className="text-muted-foreground hover:text-foreground transition-colors"
                          aria-label="View booking"
                        >
                          <ExternalLink className="h-3.5 w-3.5" />
                        </a>

                        {canAdmin && (
                          <button
                            onClick={() => setUnlinkingId(session.id)}
                            className="text-muted-foreground hover:text-destructive transition-colors"
                            aria-label="Unlink session"
                          >
                            <Unlink className="h-3.5 w-3.5" />
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </li>
              )
            })}
          </ol>
        </div>
      )}

      {/* Unlink confirmation dialog */}
      <AlertDialog
        open={unlinkingId !== null}
        onOpenChange={(open) => !open && setUnlinkingId(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Unlink this session?</AlertDialogTitle>
            <AlertDialogDescription>
              The booking will remain but will no longer be associated with this project. Session
              numbers on remaining sessions are not automatically reassigned.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => unlinkingId && handleUnlink(unlinkingId)}
              disabled={isPending}
            >
              Unlink
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

function EmptySessions() {
  return (
    <div className="flex flex-col items-center justify-center py-12 text-center rounded-lg border border-dashed border-border">
      <CalendarPlus className="h-10 w-10 text-muted-foreground mb-3" />
      <h3 className="text-sm font-semibold text-foreground mb-1">No sessions yet</h3>
      <p className="text-xs text-muted-foreground max-w-xs">
        Book the first session and link it to this project. Session numbers are assigned
        automatically.
      </p>
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { toast } from 'sonner'
import { DollarSign, PlusCircle, ArrowRight } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { MoneyInput } from '@/components/ui/money-input'
import { Progress } from '@/components/ui/progress'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Label } from '@/components/ui/label'
import { Loader2 } from 'lucide-react'
import { cn, formatCurrency, formatDate } from '@/lib/utils'
import { recordDepositAction, allocateDepositAction } from '@/app/(app)/projects/actions'
import type { ProjectWithSessions, ProjectDepositLedger } from '@/lib/projects/queries'

interface DepositTabProps {
  project: ProjectWithSessions
  ledger: ProjectDepositLedger
  role: string
  onRefresh: () => void
}

export function DepositTab({ project, ledger, role, onRefresh }: DepositTabProps) {
  const [isPending, startTransition] = useTransition()
  const [showAddDialog, setShowAddDialog] = useState(false)
  const [showAllocateDialog, setShowAllocateDialog] = useState(false)
  const [addAmount, setAddAmount] = useState(0)
  const [allocateBookingId, setAllocateBookingId] = useState<string>('')
  const [allocateAmount, setAllocateAmount] = useState(0)

  const canAdmin = role === 'owner' || role === 'admin'

  const poolProgress = ledger.total_pool_cents > 0
    ? Math.min(100, Math.round((ledger.applied_cents / ledger.total_pool_cents) * 100))
    : 0

  const unlinkedSessions = project.sessions.filter(
    (s) => !ledger.allocations.some((a) => a.booking_id === s.id)
  )

  const handleAddDeposit = () => {
    if (addAmount <= 0) {
      toast.error('Amount must be greater than zero')
      return
    }
    startTransition(async () => {
      const result = await recordDepositAction(project.id, addAmount)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success('Deposit recorded')
      setShowAddDialog(false)
      setAddAmount(0)
      onRefresh()
    })
  }

  const handleAllocate = () => {
    if (!allocateBookingId) {
      toast.error('Please select a session')
      return
    }
    if (allocateAmount <= 0) {
      toast.error('Amount must be greater than zero')
      return
    }
    if (allocateAmount > ledger.balance_cents) {
      toast.error('Amount exceeds available balance')
      return
    }
    startTransition(async () => {
      const result = await allocateDepositAction(project.id, allocateBookingId, allocateAmount)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success('Deposit allocated to session')
      setShowAllocateDialog(false)
      setAllocateBookingId('')
      setAllocateAmount(0)
      onRefresh()
    })
  }

  return (
    <div className="space-y-5 max-w-2xl">
      {/* Summary — 3 big numbers */}
      <div className="grid grid-cols-3 gap-3">
        <SummaryCard
          label="Pool"
          value={formatCurrency(ledger.total_pool_cents)}
          sub="Total deposited"
        />
        <SummaryCard
          label="Applied"
          value={formatCurrency(ledger.applied_cents)}
          sub="Allocated to sessions"
        />
        <SummaryCard
          label="Balance"
          value={formatCurrency(ledger.balance_cents)}
          sub="Available"
          highlight={ledger.balance_cents > 0}
        />
      </div>

      {/* Progress bar */}
      {ledger.total_pool_cents > 0 && (
        <div className="space-y-1">
          <div className="flex justify-between text-xs text-muted-foreground">
            <span>{poolProgress}% allocated</span>
            <span>{formatCurrency(ledger.balance_cents)} remaining</span>
          </div>
          <Progress value={poolProgress} className="h-2" />
        </div>
      )}

      {/* CTAs */}
      {canAdmin && (
        <div className="flex gap-2">
          <Button size="sm" variant="outline" onClick={() => setShowAddDialog(true)}>
            <PlusCircle className="h-3.5 w-3.5" />
            Add payment to pool
          </Button>
          {ledger.balance_cents > 0 && unlinkedSessions.length > 0 && (
            <Button size="sm" variant="outline" onClick={() => setShowAllocateDialog(true)}>
              <ArrowRight className="h-3.5 w-3.5" />
              Allocate to session
            </Button>
          )}
        </div>
      )}

      {/* Ledger table */}
      {ledger.allocations.length > 0 ? (
        <div>
          <h3 className="text-sm font-semibold text-foreground mb-2">Session allocations</h3>
          <div className="rounded-lg border border-border overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Session</TableHead>
                  <TableHead>Date</TableHead>
                  <TableHead className="text-right">Amount</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {ledger.allocations.map((alloc) => {
                  const session = project.sessions.find((s) => s.id === alloc.booking_id)
                  return (
                    <TableRow key={alloc.booking_id}>
                      <TableCell className="text-sm">
                        Session {alloc.session_number ?? '—'}
                        {session?.service && (
