'use client'

import { useState, useTransition, useRef } from 'react'
import { toast } from 'sonner'
import { ImageIcon, Trash2, Upload, ChevronUp, ChevronDown, Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { FileDropzone } from '@/components/ui/file-dropzone'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { cn } from '@/lib/utils'
import { addReferenceAction, removeReferenceAction, reorderReferencesAction } from '@/app/(app)/projects/actions'
import type { ProjectWithSessions, ProjectReference } from '@/lib/projects/queries'

interface ReferencesTabProps {
  project: ProjectWithSessions
  references: ProjectReference[]
  role: string
  onRefresh: () => void
}

export function ReferencesTab({ project, references, role, onRefresh }: ReferencesTabProps) {
  const [isPending, startTransition] = useTransition()
  const [removingId, setRemovingId] = useState<string | null>(null)
  const [uploading, setUploading] = useState(false)
  const [localOrder, setLocalOrder] = useState<string[]>(references.map((r) => r.id))

  const canWrite = role === 'owner' || role === 'admin' || role === 'artist'

  const orderedRefs = localOrder
    .map((id) => references.find((r) => r.id === id))
    .filter((r): r is ProjectReference => Boolean(r))

  const handleUpload = (files: File[]) => {
    const file = files[0]
    if (!file) return

    setUploading(true)
    startTransition(async () => {
      const fd = new FormData()
      fd.append('file', file)
      fd.set('displayOrder', String(references.length))
      const result = await addReferenceAction(project.id, fd)
      setUploading(false)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success('Reference added')
      onRefresh()
    })
  }

  const handleRemove = (refId: string) => {
    startTransition(async () => {
      const result = await removeReferenceAction(project.id, refId)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      setLocalOrder((prev) => prev.filter((id) => id !== refId))
      toast.success('Reference removed')
      onRefresh()
    })
    setRemovingId(null)
  }

  const moveItem = (id: string, direction: 'up' | 'down') => {
    const idx = localOrder.indexOf(id)
    if (idx === -1) return
    const newOrder = [...localOrder]
    const swap = direction === 'up' ? idx - 1 : idx + 1
    if (swap < 0 || swap >= newOrder.length) return
    ;[newOrder[idx], newOrder[swap]] = [newOrder[swap], newOrder[idx]]
    setLocalOrder(newOrder)

    startTransition(async () => {
      const result = await reorderReferencesAction(project.id, newOrder)
      if (!result.ok) {
        toast.error(result.error)
        // Revert
        setLocalOrder(localOrder)
      }
    })
  }

  return (
    <div className="space-y-4 max-w-3xl">
      {/* Upload zone */}
      {canWrite && (
        <FileDropzone
          accept={{ 'image/*': ['.jpg', '.jpeg', '.png', '.webp', '.gif'] }}
          maxSize={10 * 1024 * 1024}
          maxFiles={1}
          onFilesAccepted={handleUpload}
          loading={uploading}
          disabled={isPending || uploading}
        />
      )}

      {/* Grid */}
      {orderedRefs.length === 0 ? (
        <EmptyReferences canWrite={canWrite} />
      ) : (
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
          {orderedRefs.map((ref, index) => (
            <ReferenceCard
              key={ref.id}
              ref={ref}
              projectId={project.id}
              canWrite={canWrite}
              isFirst={index === 0}
              isLast={index === orderedRefs.length - 1}
              onMoveUp={() => moveItem(ref.id, 'up')}
              onMoveDown={() => moveItem(ref.id, 'down')}
              onRemove={() => setRemovingId(ref.id)}
            />
          ))}
        </div>
      )}

      {/* Remove confirmation */}
      <AlertDialog
        open={removingId !== null}
        onOpenChange={(open) => !open && setRemovingId(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove this reference?</AlertDialogTitle>
            <AlertDialogDescription>
              The image will be removed from the moodboard. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => removingId && handleRemove(removingId)}
              disabled={isPending}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Remove
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

function getPublicUrl(storagePath: string): string {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''
  return `${supabaseUrl}/storage/v1/object/public/project-references/${storagePath}`
}

interface ReferenceCardProps {
  ref: ProjectReference
  projectId: string
  canWrite: boolean
  isFirst: boolean
  isLast: boolean
  onMoveUp: () => void
  onMoveDown: () => void
  onRemove: () => void
}

function ReferenceCard({
  ref,
  canWrite,
  isFirst,
  isLast,
  onMoveUp,
  onMoveDown,
  onRemove,
}: ReferenceCardProps) {
  const [imgError, setImgError] = useState(false)

  return (
    <div className="group relative rounded-lg overflow-hidden border border-border bg-muted aspect-square shadow-[var(--shadow-soft)]">
      {!imgError ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={getPublicUrl(ref.storage_path)}
          alt={ref.caption ?? 'Reference image'}
          className="h-full w-full object-cover"
          onError={() => setImgError(true)}
        />
      ) : (
        <div className="flex h-full w-full items-center justify-center">
          <ImageIcon className="h-8 w-8 text-muted-foreground/40" />
        </div>
      )}

      {/* Caption overlay */}
      {ref.caption && (
        <div className="absolute bottom-0 inset-x-0 px-2 py-1 bg-black/50 text-white text-[11px] line-clamp-2">
          {ref.caption}
        </div>
      )}

      {/* Controls on hover */}
      {canWrite && (
        <div className="absolute top-1 right-1 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button
            onClick={onMoveUp}
            disabled={isFirst}
            className={cn(
              'p-1 rounded bg-black/40 text-white hover:bg-black/60 transition-colors',
              isFirst && 'opacity-40 cursor-not-allowed'
            )}
            aria-label="Move up"
          >
            <ChevronUp className="h-3 w-3" />
          </button>
          <button
            onClick={onMoveDown}
            disabled={isLast}
            className={cn(
              'p-1 rounded bg-black/40 text-white hover:bg-black/60 transition-colors',
              isLast && 'opacity-40 cursor-not-allowed'
            )}
            aria-label="Move down"
          >
            <ChevronDown className="h-3 w-3" />
          </button>
          <button
            onClick={onRemove}
            className="p-1 rounded bg-black/40 text-white hover:bg-destructive transition-colors"
            aria-label="Remove"
          >
            <Trash2 className="h-3 w-3" />
          </button>
        </div>
      )}
    </div>
  )
}

function EmptyReferences({ canWrite }: { canWrite: boolean }) {
  return (
    <div className="flex flex-col items-center justify-center py-12 text-center rounded-lg border border-dashed border-border">
      <ImageIcon className="h-10 w-10 text-muted-foreground mb-3" />
      <h3 className="text-sm font-semibold text-foreground mb-1">No reference images yet</h3>
      <p className="text-xs text-muted-foreground max-w-xs">
        {canWrite
          ? 'Upload reference images above to build the moodboard for this project.'
          : 'No references have been uploaded for this project yet.'}
      </p>
    </div>
  )
}

