const STYLE_LABELS: Record<string, string> = {
  traditional: 'Traditional',
  realism: 'Realism',
  neo_trad: 'Neo Traditional',
  blackwork: 'Blackwork',
  japanese: 'Japanese',
  tribal: 'Tribal',
  watercolor: 'Watercolor',
  fine_line: 'Fine Line',
  custom: 'Custom / Other',
}

interface DetailsTabProps {
  project: ProjectWithSessions
  role: string
  onRefresh: () => void
  onArchive?: () => void
}

interface EditState {
  name: string
  description: string
  placement: string
  style: string
  totalSessionsPlanned: string
  totalPriceCents: number
  moodboardUrl: string
  status: string
}

export function DetailsTab({ project, role, onRefresh, onArchive }: DetailsTabProps) {
  const [isPending, startTransition] = useTransition()
  const [isEditing, setIsEditing] = useState(false)
  const [showArchiveDialog, setShowArchiveDialog] = useState(false)

  const [editState, setEditState] = useState<EditState>({
    name: project.name,
    description: project.description ?? '',
    placement: project.placement ?? '',
    style: project.style ?? '',
    totalSessionsPlanned: project.total_sessions_planned?.toString() ?? '',
    totalPriceCents: project.total_price_cents,
    moodboardUrl: project.moodboard_url ?? '',
    status: project.status,
  })

  const canWrite = role === 'owner' || role === 'admin' || role === 'artist'
  const canAdmin = role === 'owner' || role === 'admin'

  const handleSave = () => {
    if (!editState.name.trim()) {
      toast.error('Project name is required')
      return
    }

    const fd = new FormData()
    fd.set('name', editState.name.trim())
    if (editState.description) fd.set('description', editState.description)
    if (editState.placement) fd.set('placement', editState.placement)
    if (editState.style) fd.set('style', editState.style)
    if (editState.totalSessionsPlanned) fd.set('totalSessionsPlanned', editState.totalSessionsPlanned)
    fd.set('totalPriceCents', String(editState.totalPriceCents))
    if (editState.moodboardUrl) fd.set('moodboardUrl', editState.moodboardUrl)
    fd.set('status', editState.status)

    startTransition(async () => {
      const result = await updateProjectAction(project.id, fd)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success('Project updated')
      setIsEditing(false)
      onRefresh()
    })
  }

  const handleCancel = () => {
    setEditState({
      name: project.name,
      description: project.description ?? '',
      placement: project.placement ?? '',
      style: project.style ?? '',
      totalSessionsPlanned: project.total_sessions_planned?.toString() ?? '',
      totalPriceCents: project.total_price_cents,
      moodboardUrl: project.moodboard_url ?? '',
      status: project.status,
    })
    setIsEditing(false)
  }

  return (
    <div className="space-y-4 max-w-xl">
      {/* Edit toolbar */}
      <div className="flex items-center justify-end gap-2">
        {isEditing ? (
          <>
            <Button variant="outline" size="sm" onClick={handleCancel} disabled={isPending}>
              <X className="h-3.5 w-3.5" />
              Cancel
            </Button>
            <Button size="sm" onClick={handleSave} disabled={isPending}>
              {isPending ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <Save className="h-3.5 w-3.5" />
              )}
              Save
            </Button>
          </>
        ) : (
          canWrite && (
            <Button variant="outline" size="sm" onClick={() => setIsEditing(true)}>
              <Pencil className="h-3.5 w-3.5" />
              Edit
            </Button>
          )
        )}
      </div>

      {/* Fields card */}
      <Card className="shadow-[var(--shadow-card)]">
        <CardHeader className="pb-3">
          <CardTitle className="text-base">Project details</CardTitle>
        </CardHeader>
