            ) : (
              <span className="text-sm text-foreground">{project.name}</span>
            )}
          </FieldRow>

          <FieldRow label="Description">
            {isEditing ? (
              <Textarea
                value={editState.description}
                onChange={(e) => setEditState((s) => ({ ...s, description: e.target.value }))}
                rows={3}
                maxLength={2000}
                className="resize-none"
              />
            ) : (
              <span className="text-sm text-foreground">
                {project.description || <span className="text-muted-foreground">—</span>}
              </span>
            )}
          </FieldRow>

          <FieldRow label="Placement">
            {isEditing ? (
              <Input
                value={editState.placement}
                onChange={(e) => setEditState((s) => ({ ...s, placement: e.target.value }))}
                placeholder="e.g. Left forearm"
                maxLength={100}
              />
            ) : (
              <span className="text-sm text-foreground">
                {project.placement || <span className="text-muted-foreground">—</span>}
              </span>
            )}
          </FieldRow>

          <FieldRow label="Style">
            {isEditing ? (
              <Select
                value={editState.style}
                onValueChange={(v) => setEditState((s) => ({ ...s, style: v }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select style…" />
                </SelectTrigger>
                <SelectContent>
                  {PROJECT_STYLES.map((st) => (
                    <SelectItem key={st} value={st}>
                      {STYLE_LABELS[st] ?? st}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            ) : (
              <span className="text-sm text-foreground">
                {project.style ? (STYLE_LABELS[project.style] ?? project.style) : (
                  <span className="text-muted-foreground">—</span>
                )}
              </span>
            )}
          </FieldRow>

          <FieldRow label="Sessions planned">
            {isEditing ? (
              <Input
                type="number"
                value={editState.totalSessionsPlanned}
                onChange={(e) =>
                  setEditState((s) => ({ ...s, totalSessionsPlanned: e.target.value }))
                }
                min={1}
                max={50}
                placeholder="Open-ended"
              />
            ) : (
              <span className="text-sm text-foreground">
                {project.total_sessions_planned ?? (
                  <span className="text-muted-foreground">Open-ended</span>
                )}
              </span>
            )}
          </FieldRow>

          <FieldRow label="Total price">
            {isEditing ? (
              <MoneyInput
                value={editState.totalPriceCents}
                onChange={(v) => setEditState((s) => ({ ...s, totalPriceCents: v }))}
              />
            ) : (
              <span className="text-sm text-foreground">
