                </a>
              ) : (
                <span className="text-sm text-muted-foreground">—</span>
              )
            )}
          </FieldRow>

          <FieldRow label="Status">
            {isEditing ? (
              <Select
                value={editState.status}
                onValueChange={(v) => setEditState((s) => ({ ...s, status: v }))}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="completed">Completed</SelectItem>
                  <SelectItem value="on_hold">On Hold</SelectItem>
                  <SelectItem value="cancelled">Archived</SelectItem>
                </SelectContent>
              </Select>
            ) : (
              <span className="text-sm capitalize text-foreground">
                {project.status.replace('_', ' ')}
              </span>
            )}
          </FieldRow>

          <FieldRow label="Started">
            <span className="text-sm text-foreground">
              {project.started_at ? formatDate(project.started_at) : (
                <span className="text-muted-foreground">—</span>
              )}
            </span>
          </FieldRow>

          {project.completed_at && (
            <FieldRow label="Completed">
              <span className="text-sm text-foreground">{formatDate(project.completed_at)}</span>
            </FieldRow>
          )}

          <FieldRow label="Created">
            <span className="text-sm text-muted-foreground">{formatDate(project.created_at)}</span>
          </FieldRow>
        </CardContent>
      </Card>

      {/* Danger zone */}
      {canAdmin && onArchive && project.status !== 'cancelled' && (
        <Card className="border-destructive/30 shadow-[var(--shadow-card)]">
          <CardHeader className="pb-3">
            <CardTitle className="text-base text-destructive">Danger zone</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex items-center justify-between gap-4">
              <div>
                <p className="text-sm font-medium text-foreground">Archive project</p>
                <p className="text-xs text-muted-foreground mt-0.5">
                  Hides this project from the active list. All data is preserved.
                </p>
              </div>
              <Button
                variant="outline"
                size="sm"
                className="border-destructive/50 text-destructive hover:bg-destructive hover:text-destructive-foreground shrink-0"
                onClick={onArchive}
              >
                Archive
              </Button>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

function FieldRow({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="grid grid-cols-[120px_1fr] gap-4 items-start">
      <span className="text-xs font-medium text-muted-foreground pt-1.5">{label}</span>
      <div>{children}</div>
    </div>
  )
}

