        <div className="h-12 w-12 rounded-full bg-muted flex items-center justify-center mb-4">
          <FolderKanban className="h-6 w-6 text-muted-foreground" />
        </div>
        <h3 className="text-sm font-semibold text-foreground mb-1">No projects yet</h3>
        <p className="text-sm text-muted-foreground max-w-xs mb-4">
          Projects group multi-session tattoos into a single workflow with shared deposit tracking.
        </p>
        {canCreate && (
          <Button
            size="sm"
            onClick={() => router.push(`/projects/new?clientId=${clientId}`)}
          >
            <Plus className="h-4 w-4" />
            New project for this client
          </Button>
        )}
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-semibold text-foreground">
          {projects.length} project{projects.length !== 1 ? 's' : ''}
        </h3>
        {canCreate && (
          <Button
            size="sm"
            variant="outline"
            onClick={() => router.push(`/projects/new?clientId=${clientId}`)}
          >
            <Plus className="h-4 w-4" />
            New project
          </Button>
        )}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        {projects.map((project) => (
          <ProjectCard key={project.id} project={project} />
        ))}
      </div>
    </div>
  )
}

